import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
/** Expected values were generated by the independent pinned official CLI.
 * Consumers never compute expected scores with the product WASM module. */
export async function officialQualityCase(metric, referenceSha256, distortedSha256, model) {
  const oracle=JSON.parse(await readFile(new URL('./analysis-quality-oracle.json',import.meta.url),'utf8'));
  const found=oracle.cases.find(c=>c.metric===metric&&!c.roi&&c.referenceSha256===referenceSha256&&c.distortedSha256===distortedSha256&&(!model||c.model===model));
  assert.ok(found,`Missing committed official ${metric} oracle for exact source pixels`);
  return found;
}
export function assertOfficial(actual,expected,tolerance=1e-6) {
  if(typeof expected==='number'){assert.equal(typeof actual,'number');assert.ok(Number.isFinite(actual)&&Math.abs(actual-expected)<=tolerance,`${actual} differs from official ${expected} by more than ${tolerance}`);return;}
  if(expected&&typeof expected==='object'){
    assert.equal(Array.isArray(actual),Array.isArray(expected));assert.deepEqual(Object.keys(actual).sort(),Object.keys(expected).sort());
    for(const key of Object.keys(expected))assertOfficial(actual[key],expected[key],tolerance);
  }else assert.equal(actual,expected);
}
// The pinned oracle records 1e-5 for VMAF and 1e-6 for CAMBI; preserve those
// cross-platform scalar floating-point tolerances, not rounded dB equality.
export const assertVmafOfficial=(actual,expected)=>assertOfficial(actual,expected,1e-5);
